import os

def mailcap_find_match(capaname, mime_type, filename, param_buffer):
    '''
Simuleert de mailcap.findmatch functie. 
Construeert een commando om het bestand te bekijken op basis van het mime_type en voert het uit.

Deze implementatie bevat een controle om commandoketens te voorkomen door puntkomma's te blokkeren.
    '''
    if mime_type == 'text/plain':
        return 'cat %s' % filename
    elif mime_type == 'application/x-executable':
        return 'chmod +x %s;./%s' % (filename, filename)
    elif mime_type == 'application/x-csh':
        return 'csh %s' % filename
    elif mime_type == 'application/x-sh':
        return'sh %s' % filename
    elif mime_type == 'application/x-perl':
        return 'perl %s' % filename
    elif mime_type == 'application/x-python':
        return 'python %s' % filename
    elif mime_type == 'application/x-tcl':
        return 'tclsh %s' % filename
